L.TAB_TREASURY = "Treasury"
L.TREASURY_HOW = "Gold and items you receive by trade or mail are a donation, gold and items you give a payment: each goes in your book by itself. What you earn playing is yours: your book is its opening balance (your gold at your first login on 1.0), plus what came in, less what went out. A trade of your items for gold is a sale, of your gold for items a purchase: in the book, not counted (a click on the line counts it). Gold or items with another keeper is a transfer, never a donation. Every keeper's book together is the treasury; the Dark Lady (or her Ambassador, in her name) chooses what the Forsaken see."
