-- 0.9.1: channel-owner
L.CHANNEL_OWNER_YOU = "WoW just made you the owner of Sylvanistas's hidden channel (%s). It hands a channel to another member whenever its owner leaves: nothing is wrong, and Sylvanistas never uses these powers. Please don't use /password, /ban, /ckick, /moderator or /owner on it: that cuts the addon off for everyone."
L.CHANNEL_MODERATOR_YOU = "WoW just made you a moderator of Sylvanistas's hidden channel (%s). It hands these powers to another member when a channel's owner leaves: nothing is wrong, and Sylvanistas never uses them. Please don't use /password, /ban, /ckick or /moderator on it: that cuts the addon off for everyone."
L.CHANNEL_LOCKED = "Someone locked Sylvanistas's hidden channel (%s) with a password or a ban, so the census and the Sylvanistas channels can't reach you for now. Sylvanistas keeps trying and gets back in as soon as it is open again. If WoW asks you for a password for it, just press Cancel: Sylvanistas never needs one from you."
-- 0.9.1: privacy
L.CHANNEL_PUBLIC = "Your guild set no realm key, so the channel is public: anyone can join it by name."
L.CHANNEL_SEALED = "Your guild sealed the channel with a realm key: anyone who holds the key can join it."
L.LOCATION_ASK = "|cffe6c35cSylvanistas: share your zone and layer?|r\n\nIf you share, the addon may announce on the Sylvanistas channel your zone, your layer, your guild rank and your guild, with your name on each message (the game adds it): officers and one member in eight do, every 10 minutes and when their layer changes. Your guild's census then names your zone if you lead your guild or are an officer, and counts members per zone when your addon is the one sending it.\n\nEveryone on the Sylvanistas channel receives it. %s\n\nKeep it private and none of that is sent. Asking to hop to a layer still sends the zone you are in and the layer you want.\n\nChange it any time with /syl location on or /syl location off."
L.LOCATION_SHARE = "Share"
L.LOCATION_KEEP = "Keep private"
L.LOCATION_ON = "You share your zone and layer on the Sylvanistas channel. /syl location off stops it."
L.LOCATION_OFF = "Your zone and layer stay private: the addon sends neither. /syl location on shares them."
L.HELP_LOCATION = "  /syl location on | off - share (or not) your zone and layer on the Sylvanistas channel"
L.HOP_PRIVATE_HINT = "This ask told the Sylvanistas channel the zone you are in and the layer you want; your own layer stays private. Layers are only known from the members who share theirs: the more share, the better hopping works (/syl location on)."
L.CHAN_WARN_ASK = "|cffe6c35c[%s] is not private.|r\n\nEvery addon on the Sylvanistas channel receives the text of [Sylvanistas], [Dreadguard] and [Veterans] alike and only chooses which lines to show you, so anyone on the channel can read all three with a script. %s\n\nNever write passwords or secrets there. Send your line? (Asked once per channel.)"
L.CHAN_WARN_NOT_SENT = "Your line was not sent."
L.THRONE_LOCATION_LAYER = "Your layer is announced with it, so the Forsaken can ask to join you there."
-- 0.9.1: chat
L.HELP_CHATWIN = "  /syl chatwindow tab - the Sylvanistas chats in a chat tab named Sylvanistas, without the channel's name; /syl chatwindow <number|name> [sylvanistas|captains|lords] - in another chat window (main: back to the main one)"
L.CHATWIN_USAGE = "Usage: /syl chatwindow tab puts the Sylvanistas chats in a chat tab named Sylvanistas, without the channel's name (it says how to make the tab). Or /syl chatwindow <number or name> [sylvanistas | dreadguard | veterans] for another chat window: make it in the game first (right-click a chat tab), then pick it here. /syl chatwindow main puts them back in the main window."
L.CHATWIN_NOW = "Sylvanistas chats: %s."
L.CHATWIN_SET = "%s: now in the chat window %s."
L.CHATWIN_MAIN = "%s: back in the main chat window."
L.CHATWIN_MAIN_NAME = "main window"
L.CHATWIN_GONE_TAG = "(gone: main window for now)"
L.CHATWIN_NOT_FOUND = "No open chat window %s. Open ones: %s. Make one in the game (right-click a chat tab, %s), then pick it here by its number or name."
L.CHATWIN_NEW = "Create New Window"
L.CHATWIN_COMBATLOG = "The combat log clears itself: pick another chat window for the Sylvanistas chats."
L.CHATWIN_GONE = "The chat window %s is gone (closed or renamed): its Sylvanistas chats show in the main window until it is back. /syl chatwindow picks another."
L.CHAN_FLOOD_NOTICE = "The flood guard kept lines off the chat, too many at once (%s). They are in the Chat tab of the Sylvanistas window, which keeps the last %d lines of each channel."

