-- 0.9.3: treasurer
L.TREASURER_ONLY = "Only a keeper of the treasury can change this."
L.TREASURER_SHARE_ASK = "You keep a book of the treasury of Sylvanistas (as its Treasurer, its Dark Lady, or a character the Dark Lady named). Share your book (balance, gold and items given and who gave them, the ranking) and the guild bank when you open it (its gold and items)? The Treasurer's yes also sends the names of everyone who gave before 1.0 (the early supporters, from 0.9's book).\n\nWhat the Dark Lady shows the Forsaken goes out on the Sylvanistas channel, and every client on it receives it, the names too. %s The rest goes by whisper to the Dark Lady, her Ambassador (a character the author may name to act for her) and the treasury's keepers alone, never on the channel. Change it any time with /syl treasurer on or off."
L.TREASURER_SHARE_YES = "Share"
L.TREASURER_SHARE_NO = "Keep private"
L.TREASURER_SHARE_ON = "Your treasury book and the guild bank are shared (the Dark Lady and her Ambassador see them; the Forsaken only if the Dark Lady allows it). /syl treasurer off withdraws them."
L.TREASURER_SHARE_OFF = "Your treasury book and the guild bank are yours alone (withdrawn from every screen; your addon says so again every 5 minutes while you play, for anyone who was offline). /syl treasurer on shares them."
L.HELP_TREASURER = "  /syl treasurer on|off - a keeper of the treasury shares his book and the guild bank, or not"
-- 0.9.3: inspection opt-out
L.INSPECTION_OPT_ON = "You take part in the Dark Lady's Banshee Inspection when your addon is in the sample: a 2-minute patrol of the players around you, reported to her. /syl inspection off says no."
L.INSPECTION_OPT_OFF = "You don't take part in Banshee Inspections: you still hear the Dark Lady's call, and nothing is inspected or reported. /syl inspection on takes part again."
L.HELP_INSPECTION = "  /syl inspection on|off - take part in the Dark Lady's Banshee Inspection, or not"
-- 1.0.1: the elite borders (Borders.lua)
L.HELP_BORDERS = "  /syl borders on | off - elite borders on your target, focus and your own portrait (the Dark Lady, Veterans, Dreadguards, the Dreadguard, Veterans and Raiders) and the marks on friendly players' nameplates, or none"
L.BORDERS_ON = "Elite borders on, on your target, your focus and your own portrait: gold wings for the Dark Lady, silver wings for the Dreadguard, gold for Veterans, silver for Dreadguards, bronze wings for Raiders and bronze for Veterans. With them, a mark left of the name on friendly players' nameplates (/syl nameplates). /syl borders off hides both."
L.BORDERS_ON_COUNCIL_GOLD = "Elite borders on, on your target, your focus and your own portrait: gold wings for the Dark Lady and the Dreadguard, gold for Veterans, silver for Dreadguards, bronze wings for Raiders and bronze for Veterans. With them, a mark left of the name on friendly players' nameplates (/syl nameplates). /syl borders off hides both."
L.BORDERS_OFF = "Elite borders off: none on your target, your focus or your own portrait, and no marks on nameplates. /syl borders on shows them again."
L.BORDERS_GAMEPAD = "With the gamepad UI they stay hidden: Sylvanistas leaves the game's unit frames alone there. They come back with mouse and keyboard."
-- 1.0.0: the author's preview of a border round his own portrait (Borders.lua)
L.BORDERS_PREVIEW_ON = "Border preview: %s round your own portrait, and on your target frame when you target yourself; its mark after your name on your own frame and on every friendly player's nameplate. On your screen only: nothing is sent, and a /reload forgets it. /syl borders test off ends it."
L.BORDERS_PREVIEW_ON_NO_MARK = "Border preview: %s round your own portrait, and on your target frame when you target yourself. Nameplate marks are off, so no mark shows with it (/syl nameplates on shows them). On your screen only: nothing is sent, and a /reload forgets it. /syl borders test off ends it."
L.BORDERS_PREVIEW_ON_MEMBER = "Mark preview: member, the Sylvanistas star, after your name on your own frame and on every friendly player's nameplate. The borders have no member tier: none round your portrait. On your screen only: nothing is sent, and a /reload forgets it. /syl borders test off ends it."
L.BORDERS_PREVIEW_OFF = "Border preview off: your own portrait shows your own rank's border again, if any, and the nameplates their own marks."
L.BORDERS_PREVIEW_HELP = "/syl borders test <tier> | off - a border round your own portrait and its nameplate mark, on your screen only. Tiers: %s; member: the star alone (a mark, no border)."
L.BORDERS_PREVIEW_WHEN_OFF = "Elite borders are off, so the preview waits: /syl borders on shows it."
L.BORDERS_PREVIEW_NOT_MEMBER = "Borders show only in a Sylvanistas guild: the preview waits until you are in one."
L.BORDERS_PREVIEW_COMBAT = "In combat: the borders are set up when the fight is over, and the preview shows then."
L.BORDERS_PREVIEW_MISSING = "This client has no frame or art for that border: nothing to show."
L.BORDERS_PREVIEW_TITLE = "Elite border preview"
L.BORDERS_PREVIEW_NONE = "off"
L.BORDERS_PREVIEW_NOW = "showing %s"
L.BORDERS_PREVIEW_SHOWN = "shown"
L.BORDERS_PREVIEW_TIP = "Shows this border round your own portrait, and on your target frame when you target yourself, as someone who holds it sees his own, and its mark after your name on your own frame and on every friendly player's nameplate. On your screen only: nothing is sent, and a /reload forgets it. Click it again, or type /syl borders test off, to end it."
L.BORDERS_PREVIEW_TIP_MEMBER = "Shows the star of any other Sylvanistas member after your name on your own frame and on every friendly player's nameplate (no border has it). On your screen only: nothing is sent, and a /reload forgets it. Click it again, or type /syl borders test off, to end it."
