-- 1.0.0: the King's Steward (the character the author marks in the signed titles list).
L.STEWARD_ACTING = "Acting for the Dark Lady"
L.THRONE_YOU_ARE_STEWARD = "You are the Dark Lady's Ambassador: in the %s's name you name Dark Rangers of your own beside her, the treasury's keepers and what the Forsaken see of it, and use every tool of her Dark Rangers. On the treasury her own newer word always wins."
L.THRONE_STEWARD_HINT = "In the Dark Lady's name you name Dark Rangers of your own beside her (the Dark Rangers button below), the treasury's keepers and what the Forsaken see of it (the Treasury tab), and use the Agenda, Voice of the Forsaken, Summon the Veterans, the Banshee Inspection, the portal, the Banshee Screams and the Forsaken's key (Rotate, below). Never her own list of Dark Rangers, her crown on the map, audiences, edicts, absolutions, the untabarded list or her own book."
L.HANDS_HINT_STEWARD = "Your Dark Rangers use the roll call, the inspection, the agenda, Voice of the Forsaken and the portal in the Dark Lady's name, and for the other guilds they speak with the Banshee Queen's authority ([Veterans] and Banshee Screams). You name and remove your own list, beside the Dark Lady's. The Dark Lady can't take your Dark Rangers back: you do, or the author, by removing you as Ambassador. The Dark Lady's Dark Rangers and the other Ambassadors' (below) are theirs to remove, not yours."
L.HANDS_NOTE_STEWARD = "The Forsaken's addons learn your list from your client alone: it ends 20 min after you stop repeating it, or at once if the author removes you as Ambassador."
L.HANDS_YOU_STEWARD = "%s, the Dark Lady's Ambassador, named you a Dark Ranger of the Dark Lady: the Sanctum tab is open to you."
