L.STEWARD_SET_KEEPERS = "Your Ambassador %s changed the treasury's keepers."
L.STEWARD_YOU = "The author's signed list names you the Dark Lady's Ambassador: the Sanctum tab is open to you, to act for the %s."
L.STEWARD_NO_LONGER = "You are no longer the Dark Lady's Ambassador: your list of Dark Rangers ended with it."
L.TREASURY_DETAIL_STEWARD = "The treasury as its keepers' addons send it. In the Dark Lady's name your buttons choose what the Forsaken see, and you name its keepers."
