-- 1.1: the warning while the Sylvanistas channel is public (request #8).
L.PUBLIC_NET = "Public channel: anyone who joins %s can read Sylvanistas's census and chats."
L.PUBLIC_NET_OFFICER = "Officers: seal it with the key the other guilds use (/syl key)."
L.PUBLIC_NET_SPLIT = "%d guildmates are on the sealed channel: an officer online hands you the key."
L.PUBLIC_NET_TITLE = "The Sylvanistas channel is public"
L.PUBLIC_NET_TIP = "No realm key is set, so every Sylvanistas addon meets on the public %s channel. Anyone can join it by name and, with a one-line script, read everything sent there: the census, where people are (for those who share it), the three chats ([Dreadguard] and [Veterans] too) and the screams. Sealed with a key, the channel's name and password come from the key and only players who hold it get in. An officer types /syl key <secret> once, and guildmates with the addon get the key by themselves over guild chat. Use the secret the officers of the other guilds use: a key of your own splits your guild off the Forsaken."
-- 1.1: the pinned line (request #9).
