-- 1.1 (b2-moderation): net-off of a character (Moderation.lua).
L.HELP_NETOFF = "  /syl netoff [guild] [name: reason] | /syl neton [guild] <name> - the Dark Lady, her Ambassador, a Dark Ranger or a Dreadguard: hide a character on every Sylvanistas surface for all the Forsaken, or take a guild off the Sylvanistas network; neton puts it back (/syl netoff alone lists them)"
L.NETOFF_TITLE = "Hidden by the moderators"
L.NETOFF_TIP = "The Dark Lady, her Ambassador, a Dark Ranger or a Dreadguard hid these characters for everyone with the addon: their chat lines, screams, layers and hop offers, Voice of the Forsaken, audience requests, the Dark Lady's week (entries and signups), the Board's flags and camps and the crafters' board don't show, nor their elite border or nameplate mark, and neither do those of the characters their player linked as alts. Nobody is removed from a guild or demoted, and Blizzard's ignore list is not touched. /syl block is still yours alone. A modified addon can ignore this."
L.NETOFF_YOU = "The moderators hid you for everyone with the addon (reason: %s; by %s, %s): your Sylvanistas chat lines and pinned line, screams, layers and hop, Voice, audience requests, entries and signups on the Dark Lady's week, flags and camps on the Board, listing on the crafter board, and your elite border and nameplate mark. Blizzard's chat and your guild are not touched. Ask a moderator if you think it is a mistake."
