-- 1.1 (b2-moderation): the King's rotation of the army's key (Keys.lua).
L.HELP_KEY_ROTATE = "  /syl key rotate - the Dark Lady or her Ambassador: a new key for all the Forsaken; she picks the guilds, their Veterans and Dreadguards her /who saw in them get it by whisper and their guilds over guild chat (never on the Sylvanistas channel)"
L.KEY_ROTATE_TITLE = "The Forsaken's key"
L.KEY_ROTATE = "Rotate the Forsaken's key"
L.KEY_ROTATE_TIP = "A new key, made by your addon and never shown (not on your stream either). You pick which guilds get it (those your /who saw are checked); it goes by whisper to their Veterans and Dreadguards online whom your /who saw in them (a census row alone is anyone's word), who hand it to their guilds over guild chat: it never travels on the Sylvanistas channel. Whoever holds the old key outside the guilds you pick stays behind on the old channel; anyone in a guild that gets it has it too."
L.KEY_ROTATE_CONFIRM = "Rotate the Forsaken's key? Your addon makes a new one (nobody sees it, you neither). You then pick on the Sanctum which guilds get it, and nothing is sent before you hand it out: it goes by whisper to their Veterans and Dreadguards online whom your /who saw in them, and each hands it to their guild over guild chat. You and your guild move to it %s minutes after you hand it out (or when you say). A Veteran or Dreadguard who logs in meanwhile gets nothing until your /who sees them in their guild (click the Sanctum's /who line). A guild with no officer online by then stays on the old channel until one of its officers types the key by hand."
L.KEY_GUILD_ROTATE_CONFIRM = "Rotate the channel key? Your addon makes a new one (nobody sees it, you neither), moves you to it and hands it to the guild over guild chat. Guildmates online follow at once; the others when a Dreadguard is online at their login."
L.KEY_GUILD_ROTATED = "Channel key rotated: the guild is moving to the new channel. Nobody saw the key."
L.HELP_KEY_GUILD_ROTATE = "  /syl key rotate - a Dreadguard: a new channel key for the guild, made by the addon (nobody sees it) and handed out over guild chat"
L.KEY_ROTATE_ONLY_KING = "Only the Dark Lady or a Dreadguard rotates the channel key. Any Dreadguard can also set one by hand with /syl key <secret>."
L.KEY_ROTATE_BUSY = "A new key is waiting on the Sanctum: hand it out and move to it, or drop it, first."
L.KEY_ROTATED = "The new Forsaken key goes by whisper to the Veterans and Dreadguards online of the guilds you picked whom your /who saw in them. You and your guild move to it in %d minutes, or sooner from the Sanctum."
L.KEY_ROTATING = "Handed to %d Veterans and Dreadguards, %d have it (%d guilds)"
L.KEY_MOVE_NOW = "Move to the new key now (in %d min anyway)"
L.KEY_MOVE_CONFIRM = "Move to the new key now? Your guild follows you. Veterans and Dreadguards who log in later no longer get it by whisper."
L.KEY_ROTATION_MOVED = "You and your guild are on the new Forsaken key: the old channel is left behind."
L.KEY_ROTATED_AGO = "Rotated %s: %d Veterans and Dreadguards have it (%d guilds)"
L.KEY_ROTATED_TAKEN = "The Forsaken's channel key changed (the Dark Lady's new key, or your officers'): joining the new channel."
