	-- 0.9.1: channel-owner
	L.CHANNEL_OWNER_YOU = "O WoW acabou de te fazer dono do canal oculto do Sylvanistas (%s). Ele passa o canal pra outro membro sempre que o dono sai: não tem nada de errado, e o Sylvanistas nunca usa esses poderes. Por favor, não use /senha, /banir, /cexpulsar, /moderador ou /dono nele: isso desliga o addon pra todo mundo."
	L.CHANNEL_MODERATOR_YOU = "O WoW acabou de te fazer moderador do canal oculto do Sylvanistas (%s). Ele passa esses poderes pra outro membro quando o dono de um canal sai: não tem nada de errado, e o Sylvanistas nunca usa eles. Por favor, não use /senha, /banir, /cexpulsar ou /moderador nele: isso desliga o addon pra todo mundo."
	L.CHANNEL_LOCKED = "Alguém trancou o canal oculto do Sylvanistas (%s) com senha ou ban, então o censo e os canais Sylvanistas não chegam em você por enquanto. O Sylvanistas continua tentando e volta assim que o canal abrir de novo. Se o WoW pedir uma senha pra ele, é só apertar Cancelar: o Sylvanistas nunca precisa de uma senha sua."
	-- 0.9.1: privacy
	L.CHANNEL_PUBLIC = "Sua guilda não definiu uma chave de reino, então o canal é público: qualquer um pode entrar nele pelo nome."
	L.CHANNEL_SEALED = "Sua guilda selou o canal com uma chave de reino: qualquer um que tenha a chave pode entrar nele."
	L.LOCATION_ASK = "|cffe6c35cSylvanistas: compartilhar sua zona e seu layer?|r\n\nSe você compartilhar, o addon pode anunciar no canal Sylvanistas sua zona, seu layer, seu rank na guilda e sua guilda, com seu nome em cada mensagem (o jogo coloca): os officers e um membro em cada oito anunciam, a cada 10 minutos e quando o layer muda. O censo da sua guilda passa a mostrar sua zona se você for o líder ou officer, e a contar os membros por zona quando é o seu addon que o envia.\n\nTodos no canal Sylvanistas recebem isso. %s\n\nSe mantiver privado, nada disso é enviado. Pedir para pular de layer ainda envia a zona onde você está e o layer que você quer.\n\nMude quando quiser com /syl location on ou /syl location off."
	L.LOCATION_SHARE = "Compartilhar"
	L.LOCATION_KEEP = "Manter privado"
	L.LOCATION_ON = "Você compartilha sua zona e seu layer no canal Sylvanistas. /syl location off para."
	L.LOCATION_OFF = "Sua zona e seu layer ficam privados: o addon não envia nenhum dos dois. /syl location on compartilha."
	L.HELP_LOCATION = "  /syl location on | off - compartilhar (ou não) sua zona e seu layer no canal Sylvanistas"
	L.HOP_PRIVATE_HINT = "Este pedido contou ao canal Sylvanistas a zona onde você está e o layer que você quer; seu próprio layer continua privado. Os layers só são conhecidos pelos membros que compartilham os deles: quanto mais compartilham, melhor o pulo funciona (/syl location on)."
	L.CHAN_WARN_ASK = "|cffe6c35c[%s] não é privado.|r\n\nTodo addon no canal Sylvanistas recebe o texto de [Sylvanistas], [Dreadguard] e [Veteranos] do mesmo jeito e só escolhe quais linhas te mostrar, então qualquer um no canal pode ler os três com um script. %s\n\nNunca escreva senhas ou segredos ali. Enviar sua linha? (Perguntado uma vez por canal.)"
	L.CHAN_WARN_NOT_SENT = "Sua linha não foi enviada."
	L.THRONE_LOCATION_LAYER = "Seu layer é anunciado junto, para os Renegados poderem pedir para entrar nele."
	-- 0.9.1: chat
	L.HELP_CHATWIN = "  /syl chatwindow tab - os chats Sylvanistas numa aba de chat chamada Sylvanistas, sem o nome do canal; /syl chatwindow <número|nome> [sylvanistas|captains|lords] - em outra janela de chat (main: de volta à principal)"
	L.CHATWIN_USAGE = "Uso: /syl chatwindow tab põe os chats Sylvanistas numa aba de chat chamada Sylvanistas, sem o nome do canal (explica como criar a aba). Ou /syl chatwindow <número ou nome> [sylvanistas | dreadguard | veterans] para outra janela de chat: crie no jogo antes (botão direito numa aba do chat) e escolha aqui. /syl chatwindow main devolve os chats à janela principal."
