	-- 0.9.3: treasurer
	L.TREASURER_ONLY = "Só um guardião do tesouro pode mudar isso."
	L.TREASURER_SHARE_ASK = "Você guarda um livro do tesouro de Sylvanistas (como Tesoureiro, como Dama Sombria, ou como personagem nomeado pela Dama Sombria). Compartilhar o seu livro (saldo, ouro e itens dados e quem deu, o ranking) e o banco da guilda quando você o abrir (ouro e itens)? O sim do Tesoureiro também envia os nomes de todos que doaram antes da 1.0 (os primeiros apoiadores, do livro da 0.9).\n\nO que a Dama Sombria mostra aos Renegados sai no canal Sylvanistas, e todo cliente nele recebe, os nomes também. %s O resto vai por sussurro só à Dama Sombria, ao Embaixador dela (um personagem que o autor pode nomear para agir por ela) e aos guardiões do tesouro, nunca no canal. Mude quando quiser com /syl treasurer on ou off."
	L.TREASURER_SHARE_YES = "Compartilhar"
	L.TREASURER_SHARE_NO = "Manter privado"
	L.TREASURER_SHARE_ON = "Seu livro do tesouro e o banco da guilda estão compartilhados (a Dama Sombria e o Embaixador dela veem; os Renegados só se a Dama Sombria permitir). /syl treasurer off retira."
	L.TREASURER_SHARE_OFF = "Seu livro do tesouro e o banco da guilda são só seus (retirados de toda tela; o seu addon repete isso a cada 5 minutos enquanto você joga, para quem estava offline). /syl treasurer on compartilha."
