	L.HELP_BORDERS = "  /syl borders on | off - bordas de elite no seu alvo, no seu foco e no seu próprio retrato (a Dama Sombria, Veteranos, Dreadguards, o Dreadguard, Veteranos e Raiders) e as marcas nas placas de identificação dos jogadores aliados, ou nenhuma"
	L.BORDERS_ON = "Bordas de elite ligadas no seu alvo, no seu foco e no seu próprio retrato: dourada com asas para a Dama Sombria, prateada com asas para o Dreadguard, dourada para Veteranos, prateada para Dreadguards, bronze com asas para Raiders e bronze para Veteranos. Com elas, uma marca à esquerda do nome nas placas de identificação dos jogadores aliados (/syl nameplates). /syl borders off esconde as duas."
	L.BORDERS_ON_COUNCIL_GOLD = "Bordas de elite ligadas no seu alvo, no seu foco e no seu próprio retrato: dourada com asas para a Dama Sombria e o Dreadguard, dourada para Veteranos, prateada para Dreadguards, bronze com asas para Raiders e bronze para Veteranos. Com elas, uma marca à esquerda do nome nas placas de identificação dos jogadores aliados (/syl nameplates). /syl borders off esconde as duas."
	L.BORDERS_OFF = "Bordas de elite desligadas: nenhuma no seu alvo, no seu foco ou no seu próprio retrato, e nenhuma marca nas placas de identificação. /syl borders on mostra de novo."
	L.BORDERS_GAMEPAD = "Com a interface de gamepad elas ficam escondidas: lá o Sylvanistas deixa em paz os quadros de unidade do jogo. Elas voltam com mouse e teclado."
	L.BORDERS_PREVIEW_ON = "Prévia de borda: %s em volta do seu próprio retrato, e no quadro do alvo quando você mira em si mesmo; a marca dela depois do seu nome no seu quadro e na placa de identificação de todo jogador aliado. Só na sua tela: nada é enviado, e um /reload esquece. /syl borders test off encerra."
	L.BORDERS_PREVIEW_ON_NO_MARK = "Prévia de borda: %s em volta do seu próprio retrato, e no quadro do alvo quando você mira em si mesmo. As marcas nas placas de identificação estão desligadas, então nenhuma marca aparece com ela (/syl nameplates on mostra). Só na sua tela: nada é enviado, e um /reload esquece. /syl borders test off encerra."
	L.BORDERS_PREVIEW_ON_MEMBER = "Prévia de marca: member, a estrela do Sylvanistas, depois do seu nome no seu quadro e na placa de identificação de todo jogador aliado. As bordas não têm o nível member: nenhuma em volta do seu retrato. Só na sua tela: nada é enviado, e um /reload esquece. /syl borders test off encerra."
