-- chats on or off, and the switches that stay off until answered.
---------------------------------------------------------------------------
L.CONSENT_TITLE = "Sylvanistas: what this addon shares"
L.CONSENT_INTRO = "While you are in a Sylvanistas guild, two things always go out. One member of your guild, elected by the addons, sends your guild's census on the Sylvanistas channel: its size, online count, classes, levels and rank names, its leader and officers (name, online, days away, class, level) and its five highest-level members (name, level, class), online or not. And your addon says hello to your guild: its version, your realm, whether your channel is public or sealed and whether you share your zone. %s"
L.CONSENT_OPTIONAL = "Nothing below goes out, or shows, until you say Yes. Until you answer, each one stays off, unless its line says a yes you gave before still stands."
L.CONSENT_FOOTER = "The window, the census and your own guild's roster work whatever you answer. Change any answer later: /syl privacy opens this page again."
L.CONSENT_DONE = "Done"
L.CONSENT_YES = "Yes"
L.CONSENT_NO = "No"
L.CONSENT_STATE_YES = "Yes"
L.CONSENT_STATE_NO = "No"
L.CONSENT_STATE_NONE = "Not answered: off"
L.CONSENT_LOCATION = "Your zone and layer"
L.CONSENT_LOCATION_TEXT = "Your zone, your layer, your guild rank and your guild, with your name, to everyone on the Sylvanistas channel (officers and one member in eight announce them, every 10 minutes and when the layer changes), and your guild's members per zone in its census. Layer hops work better the more members share. (/syl location on|off)"
L.CONSENT_LAYERHELP = "Help others join your layer"
L.CONSENT_LAYERHELP_TEXT = "When someone asks for the layer you are on, your addon may whisper them alone that you are there, and then asks you whether to invite them (you click Invite). (/syl layerhelp on|off)"
L.CONSENT_NEEDS_LOCATION = "Only while you share your zone and layer."
L.CONSENT_TREASURER = "Your book of the treasury (keepers)"
L.CONSENT_TREASURER_TEXT = "Your book (its balance, the gold and items given and who gave them, the ranking of donors) and the guild bank of <Sylvanistas>, to everyone on the Sylvanistas channel, every 5 minutes while you play. The addon shows them to the Dark Lady and her Ambassador, and to the Forsaken only with the Dark Lady's switches. (/syl treasurer on|off)"
L.CONSENT_TREASURER_EARLY = "As the Treasurer, your Yes also sends the names of everyone who gave before 1.0 (the early supporters, from 0.9's book): every client on the Sylvanistas channel receives them, the names too."
L.CONSENT_TREASURER_OLD_YES = "Your yes of 0.9.3 still sends your book until you answer here."
L.CONSENT_INSPECTION = "The Dark Lady's Banshee Inspection"
L.CONSENT_INSPECTION_TEXT = "When the Dark Lady, her Ambassador or a Dark Ranger calls one and your addon is in the sample, it inspects the Sylvanistas players around you for 2 minutes, then whispers whoever called it alone: your guild, how many wore the guild tabard, another one or none, and up to 6 names of players caught without the colors. You get its raid warning either way. (/syl inspection on|off)"
L.CONSENT_ROLLCALL = "The author's roll call"
L.CONSENT_ROLLCALL_TEXT = "When the addon's author asks, your addon whispers him alone its version, the game client, and whether it joined the channel, is your guild's reporter and has the channel sealed. Nothing about your character. His update notices show unless you say No. (/syl rollcall on|off)"
L.CONSENT_CHAT = "The Sylvanistas chats"
L.CONSENT_CHAT_TEXT = "[Sylvanistas], [Dreadguard] and [Veterans] (/sy, /syd, /syv), and the pinned line. Yes: other players' lines show here, and you can write; every line you write reaches everyone on the Sylvanistas channel. No: this client neither sends nor shows them. (/syl chat on|off)"
L.CHAT_ON_MSG = "Sylvanistas chats on: other players' [Sylvanistas], [Dreadguard] and [Veterans] lines show here, and /sy, /syd and /syv send. /syl chat off turns them off."
L.CHAT_OFF_MSG = "Sylvanistas chats off: this client neither sends nor shows [Sylvanistas], [Dreadguard] or [Veterans]. /syl chat on turns them on."
L.CHAT_OFF = "The Sylvanistas chats are off on this client: nothing was sent. /syl chat on turns them on."
L.CHAT_OFF_UNANSWERED = "The Sylvanistas chats stay off on this client until you choose: /syl privacy (the Sylvanistas page) or /syl chat on."
L.CHATS_OFF_LINK = "Sylvanistas chats: off on this client (click to choose)"
L.HELP_PRIVACY_PAGE = "  /syl privacy - what this addon shares, and your answer to each (the first-open page)"
L.HELP_CHAT = "  /syl chat on|off - the Sylvanistas chats on this client (off: nothing sent, nothing shown)"
L.INSPECTION_OPT_UNANSWERED = "You don't take part in Banshee Inspections until you say yes (/syl inspection on, or the Sylvanistas page: /syl privacy). You still hear the Dark Lady's call."
L.ROLLCALL_UNANSWERED = "The author's roll calls are not answered until you say yes (/syl rollcall on, or the Sylvanistas page: /syl privacy). His update notices still show."
if GetLocale and GetLocale() == "ptBR" then
	L.CONSENT_TITLE = "Sylvanistas: o que este addon compartilha"
	L.CONSENT_INTRO = "Enquanto você está numa guilda Sylvanistas, duas coisas sempre saem. Um membro da sua guilda, eleito pelos addons, manda o censo da sua guilda no canal Sylvanistas: tamanho, quantos online, classes, níveis e nomes das patentes, o líder e os oficiais (nome, online, dias ausente, classe, nível) e os cinco membros de nível mais alto (nome, nível, classe), online ou não. E o seu addon dá oi para a sua guilda: a versão dele, o seu reino, se o seu canal é público ou selado e se você compartilha a sua zona. %s"
	L.CONSENT_OPTIONAL = "Nada abaixo sai, nem aparece, até você dizer Sim. Até você responder, cada um fica desligado, a menos que a linha diga que um sim que você deu antes ainda vale."
	L.CONSENT_FOOTER = "A janela, o censo e o rol da sua própria guilda funcionam seja qual for a resposta. Para mudar depois: /syl privacy abre esta página de novo."
	L.CONSENT_DONE = "Pronto"
	L.CONSENT_YES = "Sim"
	L.CONSENT_NO = "Não"
	L.CONSENT_STATE_YES = "Sim"
	L.CONSENT_STATE_NO = "Não"
	L.CONSENT_STATE_NONE = "Sem resposta: desligado"
	L.CONSENT_LOCATION = "Sua zona e seu layer"
	L.CONSENT_LOCATION_TEXT = "Sua zona, seu layer, sua patente e sua guilda, com o seu nome, para todos no canal Sylvanistas (os oficiais e um membro em cada oito anunciam, a cada 10 minutos e quando o layer muda), e os membros da sua guilda por zona no censo dela. O salto de layer funciona melhor quanto mais membros compartilham. (/syl location on|off)"
	L.CONSENT_LAYERHELP = "Ajudar outros a entrar no seu layer"
	L.CONSENT_LAYERHELP_TEXT = "Quando alguém pede o layer em que você está, o seu addon pode sussurrar só para essa pessoa que você está lá, e depois pergunta se você convida (você clica em Convidar). (/syl layerhelp on|off)"
	L.CONSENT_NEEDS_LOCATION = "Só enquanto você compartilha a sua zona e o seu layer."
	L.CONSENT_TREASURER = "Seu livro do tesouro (guardiões)"
	L.CONSENT_TREASURER_TEXT = "O seu livro (saldo, o ouro e os itens doados e quem doou, o ranking de doadores) e o banco da guilda <Sylvanistas>, para todos no canal Sylvanistas, a cada 5 minutos enquanto você joga. O addon mostra à Dama Sombria e ao Embaixador dela, e aos Renegados só com os botões da Dama Sombria. (/syl treasurer on|off)"
	L.CONSENT_TREASURER_EARLY = "Como Tesoureiro, o seu Sim também envia os nomes de todos que doaram antes da 1.0 (os primeiros apoiadores, do livro da 0.9): todo cliente no canal Sylvanistas os recebe, os nomes também."
	L.CONSENT_TREASURER_OLD_YES = "O seu sim da 0.9.3 ainda envia o seu livro até você responder aqui."
	L.CONSENT_INSPECTION = "A Inspeção Banshee da Dama Sombria"
	L.CONSENT_INSPECTION_TEXT = "Quando a Dama Sombria, o Embaixador dela ou um Patrulheiro Sombrio convoca uma e o seu addon cai na amostra, ela inspeciona os jogadores Sylvanistas ao seu redor por 2 minutos e depois sussurra só para quem convocou: a sua guilda, quantos usavam o tabardo da guilda, outro ou nenhum, e até 6 nomes de quem foi pego sem as cores. O aviso de raide chega de qualquer jeito. (/syl inspection on|off)"
	L.CONSENT_ROLLCALL = "A chamada do autor"
	L.CONSENT_ROLLCALL_TEXT = "Quando o autor do addon pergunta, o seu addon sussurra só para ele a versão, o cliente do jogo, e se entrou no canal, se é o repórter da sua guilda e se o canal está selado. Nada sobre o seu personagem. Os avisos de atualização dele aparecem, a menos que você diga Não. (/syl rollcall on|off)"
	L.CONSENT_CHAT = "Os chats Sylvanistas"
	L.CONSENT_CHAT_TEXT = "[Sylvanistas], [Dreadguard] e [Veteranos] (/sy, /syd, /syv), e a linha fixada. Sim: as linhas dos outros jogadores aparecem aqui, e você pode escrever; cada linha que você escreve chega a todos no canal Sylvanistas. Não: este cliente não manda nem mostra esses chats. (/syl chat on|off)"
	L.CHAT_ON_MSG = "Chats Sylvanistas ligados: as linhas de [Sylvanistas], [Dreadguard] e [Veteranos] dos outros aparecem aqui, e /sy, /syd e /syv mandam. /syl chat off desliga."
	L.CHAT_OFF_MSG = "Chats Sylvanistas desligados: este cliente não manda nem mostra [Sylvanistas], [Dreadguard] ou [Veteranos]. /syl chat on liga."
	L.CHAT_OFF = "Os chats Sylvanistas estão desligados neste cliente: nada foi mandado. /syl chat on liga."
	L.CHAT_OFF_UNANSWERED = "Os chats Sylvanistas ficam desligados neste cliente até você escolher: /syl privacy (a página do Sylvanistas) ou /syl chat on."
	L.CHATS_OFF_LINK = "Chats Sylvanistas: desligados neste cliente (clique para escolher)"
	L.HELP_PRIVACY_PAGE = "  /syl privacy - o que este addon compartilha, e a sua resposta a cada um (a página da primeira abertura)"
	L.HELP_CHAT = "  /syl chat on|off - os chats Sylvanistas neste cliente (desligados: nada é mandado nem mostrado)"
	L.INSPECTION_OPT_UNANSWERED = "Você não participa das Inspeções Banshee até dizer sim (/syl inspection on, ou a página do Sylvanistas: /syl privacy). Você ainda ouve o chamado da Dama Sombria."
	L.ROLLCALL_UNANSWERED = "As chamadas do autor não são respondidas até você dizer sim (/syl rollcall on, ou a página do Sylvanistas: /syl privacy). Os avisos de atualização dele ainda aparecem."
