	-- 1.1 (b2-moderation): net-off de um personagem (Moderation.lua).
	L.HELP_NETOFF = "  /syl netoff [guild] [nome: motivo] | /syl neton [guild] <nome> - a Dama Sombria, o Embaixador dela, um Patrulheiro Sombrio ou um Dreadguard: esconde um personagem em tudo do Sylvanistas para todos os Renegados, ou tira uma guilda da rede do Sylvanistas; neton devolve (/syl netoff sozinho lista)"
	L.NETOFF_TITLE = "Escondidos pelos moderadores"
	L.NETOFF_TIP = "A Dama Sombria, o Embaixador dela, um Patrulheiro Sombrio ou um Dreadguard esconderam esses personagens para todo mundo com o addon: as falas no chat, os gritos, as camadas e ofertas de salto, a Voz dos Renegados, os pedidos na audiência, a semana da Dama Sombria (entradas e inscrições), as bandeiras e acampamentos do Mural e a lista de artesãos deles não aparecem, nem a borda de elite ou a marca na placa de identificação, nem os dos personagens que o jogador ligou como alts. Ninguém sai da guilda nem perde cargo, e a lista de ignorados da Blizzard não é tocada. O /syl block continua sendo só seu. Um addon modificado pode ignorar isso."
	L.NETOFF_YOU = "Os moderadores esconderam você para todo mundo com o addon (motivo: %s; por %s, %s): as suas falas nos chats do Sylvanistas e a sua linha fixada, os gritos, as camadas e saltos, a Voz, os pedidos na audiência, as entradas e inscrições na semana da Dama Sombria, as bandeiras e acampamentos no Mural, o seu anúncio no quadro de artesãos, e a sua borda de elite e marca na placa de identificação. O chat da Blizzard e a sua guilda não são tocados. Fale com um moderador se achar que foi um engano."
	L.NETOFF_YOU_SHORT = "Você está escondido pelos moderadores (passe o mouse para ver o motivo)"
	L.NETOFF_YOU_BACK = "Os moderadores mostraram você de novo: as suas falas nos chats do Sylvanistas e a sua linha fixada, os gritos, as camadas e saltos, a Voz, os pedidos na audiência, as entradas e inscrições na semana da Dama Sombria, as bandeiras e acampamentos no Mural, o seu anúncio no quadro de artesãos, a borda de elite e a marca na placa de identificação voltam a aparecer para todo mundo."
	L.NETOFF_ONLY = "Só a Dama Sombria, o Embaixador dela, um Patrulheiro Sombrio ou um Dreadguard podem esconder um personagem para os Renegados. /syl block <nome> esconde só para você."
