	-- 1.1 (b2-moderation): a troca da chave do exército pelo Rei (Keys.lua).
	L.HELP_KEY_ROTATE = "  /syl key rotate - a Dama Sombria ou o Embaixador dela: uma chave nova para todos os Renegados; ela escolhe as guildas, os Veteranos e Dreadguards delas que o /who dela viu nelas recebem por sussurro e as guildas pelo chat da guilda (nunca no canal do Sylvanistas)"
	L.KEY_ROTATE_TITLE = "A chave dos Renegados"
	L.KEY_ROTATE = "Trocar a chave dos Renegados"
	L.KEY_ROTATE_TIP = "Uma chave nova, feita pelo seu addon e nunca mostrada (nem na sua live). Você escolhe quais guildas recebem (as que o seu /who viu vêm marcadas); ela vai por sussurro aos Veteranos e Dreadguards online delas que o seu /who viu nelas (uma linha do censo sozinha é palavra de qualquer um), que a passam para as guildas pelo chat da guilda: nunca passa pelo canal do Sylvanistas. Quem tem a chave antiga fora das guildas que você escolher fica para trás no canal antigo; quem está numa guilda que recebe fica com ela também."
	L.KEY_ROTATE_CONFIRM = "Trocar a chave dos Renegados? O seu addon faz uma nova (ninguém vê, nem você). Depois você escolhe no Santuário quais guildas recebem, e nada é enviado antes de você entregar: ela vai por sussurro aos Veteranos e Dreadguards online delas que o seu /who viu nelas, e cada um passa para a guilda dele pelo chat da guilda. Você e a sua guilda passam para ela %s minutos depois da entrega (ou quando você mandar). Um Veterano ou Dreadguard que entrar nesse meio-tempo não recebe nada até o seu /who vê-lo na guilda dele (clique na linha /who do Santuário). Uma guilda sem oficial online até lá fica no canal antigo até um oficial dela digitar a chave."
	L.KEY_ROTATE_ONLY_KING = "Só a Dama Sombria ou um Dreadguard troca a chave do canal. Qualquer Dreadguard também pode definir uma à mão com /syl key <segredo>."
