L.CHATTAB_SET = "%s: now in your Sylvanistas tab, each line in its channel's colour, without the channel's name."
L.CHATTAB_HERE = "The Sylvanistas chats show in this tab, each line in its channel's colour: %s. /syl chatwindow main puts them back in the main window."
