L.CHATTY_STEPS = "No Chattynator tab named Sylvanistas yet. Make it in Chattynator: click the + after its tabs (unlock the chat first if it is locked), right-click the new tab, Rename tab, and name it Sylvanistas; then right-click it, Tab Settings, and under Addons tick Sylvanistas. The Sylvanistas chats go there as soon as it exists (the main window until then)."
L.CHATTY_FILTER = "Chattynator's tab %s shows the Sylvanistas chats only if its filter lets Sylvanistas in: right-click the tab, Tab Settings, and under Addons tick Sylvanistas (or All Addons). Sylvanistas cannot see that filter."
