L.CHATSET_WHERE_TIP_CHATTY = "The Chattynator tab its lines print in. A click moves them to its next tab, then back to the main window, as /syl chatwindow does; nothing of Chattynator's is changed. For a new tab: the + after its tabs; then, in its Tab Settings, tick Sylvanistas under Addons."
if GetLocale and GetLocale() == "ptBR" then
	L.CHATTY_STEPS = "Ainda não há aba do Chattynator chamada Sylvanistas. Crie no Chattynator: clique no + depois das abas dele (destrave o chat antes, se estiver travado), botão direito na aba nova, Renomear aba, e dê o nome Sylvanistas; depois botão direito nela, Configurações da aba, e em Addons marque Sylvanistas. Os chats Sylvanistas vão para lá assim que ela existir (até lá, a janela principal)."
	L.CHATTY_FILTER = "A aba %s do Chattynator só mostra os chats Sylvanistas se o filtro dela deixar o Sylvanistas entrar: botão direito na aba, Configurações da aba, e em Addons marque Sylvanistas (ou Todos os addons). O Sylvanistas não vê esse filtro."
	L.CHATTY_NOT_FOUND = "Nenhuma aba do Chattynator chamada %s. Abas dele: %s. Crie uma no Chattynator (o + depois das abas dele) e escolha aqui pelo nome."
	L.CHATTY_TAB_STEPS = "Esperando a sua aba Sylvanistas: no Chattynator, clique no + depois das abas dele e dê o nome Sylvanistas à aba nova (botão direito nela, Renomear aba)."
	L.CHATSET_WHERE_TIP_CHATTY = "A aba do Chattynator onde as linhas dele aparecem. Um clique as leva para a próxima aba dele, e depois de volta à janela principal, como /syl chatwindow faz; nada do Chattynator é mudado. Para uma aba nova: o + depois das abas dele; depois, nas Configurações da aba, marque Sylvanistas em Addons."
